      // gh-1440: the freshness knob rides the same section — a toggle
      // merge must not drop it.
      if (section['liveRediscovery'] != null) {
        buffer.write('  liveRediscovery: ${section['liveRediscovery']}\n');
      }
    }
    buffer.write(
      SkillsConfig(skills: {...seed.config.skills, name: enabled}).toYaml(),
    );
    final body = (source == null || source.trim().isEmpty)
        ? buffer.toString()
        : _replaceTopLevelYamlBlock(source, 'skills', buffer.toString());
    return '$body\n';
