      }
    }
    buffer.write(
      SkillsConfig(skills: {...seed.config.skills, name: enabled}).toYaml(),
    );
    final body = (source == null || source.trim().isEmpty)
        ? buffer.toString()
        : _replaceTopLevelYamlBlock(source, 'skills', buffer.toString());
    return '$body\n';
  }

