/// The segment-close log line (gh-1241 surface 2): one `fa-tokens:` line
/// per closed segment keeps the dmtools-agents dashboard's log-grepping
/// reporter (`js/aiTeammateTokenUsageReporter.js`) alive with a one-line
/// parser change — the reporter greps for [usageTokensLogPrefix] and
/// JSON-parses the rest, so the payload is compact single-line JSON with
/// the documented key order.
///
/// [usageTokensLogPattern] is the PINNED fixture (IT-7/AC7): the test
/// suite asserts every emitted line matches it, so the external parser
/// can rely on the shape without running fa.
library;

import 'dart:convert';

import 'usage_ledger.dart';

/// The exact prefix the reporter greps for.
const String usageTokensLogPrefix = 'fa-tokens: ';

/// The pinned one-line shape (AC7): every field documented in gh-1241,
/// compact JSON, fixed key order. `source` is the segment's marker (I3).
final RegExp usageTokensLogPattern = RegExp(
  r'^fa-tokens: \{"sessionId":"[^"]*","segment":[0-9]+,'
  r'"input":[0-9]+,"output":[0-9]+,"cacheRead":[0-9]+,'
  r'"requests":[0-9]+,"source":"(reported|estimated|mixed)"\}$',
);

/// Builds the segment-close line for [segment] of [sessionId] — compact,
/// key order fixed, matching [usageTokensLogPattern] by construction.
String usageTokensLogLine({
  required String sessionId,
  required UsageSegment segment,
}) =>
    '$usageTokensLogPrefix${jsonEncode({'sessionId': sessionId, 'segment': segment.index, 'input': segment.totals.input, 'output': segment.totals.output, 'cacheRead': segment.totals.cacheRead, 'requests': segment.totals.requests, 'source': segment.source.wire})}';
factory / guard success 114026906636
factory / teammate success 114027014140

leg tokens: ${KEY} ${LEG} prompt=${SUM_IN} completion=${SUM_OUT}"[0m
leg tokens: issue-1440 dev prompt=77737 completion=4711
fa-tokens: {"sessionId":"01a120ab-595f-7fff-94ea-489b29069328","segment":2,"input":77737,"output":4711,"cacheRead":1927744,"requests":24,"source":"reported"}

read -r SUM_IN SUM_OUT < <(python3 - "${RUN_OUTPUT}" <<'PY' || true
import json, re, sys
inp = out = 0
try:
    text = open(sys.argv[1], encoding="utf-8", errors="replace").read()
except OSError:
    print(0, 0); raise SystemExit
for m in re.finditer(r"fa-tokens:[ \t]*(\{)", text):
    depth, i = 0, m.start(1)
    for i in range(m.start(1), len(text)):
        if text[i] == "{": depth += 1
        elif text[i] == "}":
            depth -= 1
            if depth == 0: break
    try:
        rec = json.loads(text[m.start(1):i + 1])
        inp += int(rec.get("input") or 0)
        out += int(rec.get("output") or 0)
    except Exception:
        continue
print(inp, out)
PY
) || true
SUM_IN="${SUM_IN:-0}"
SUM_OUT="${SUM_OUT:-0}"
if [ "${SUM_IN}" = "0" ] && [ "${SUM_OUT}" = "0" ]; then
  echo "::warning::no fa-tokens ledger line in run output — skipping token publish"
  exit 0
fi
case "$(basename "${CONFIG:-}" .json)" in
  *rework*) LEG="rework" ;;
  *) LEG="${KIND:-dev}" ;;
esac
case "${ANCHOR}" in
  pr-*) KEY="${ANCHOR}" ;;
  gh-*) KEY="issue-${ANCHOR#gh-}" ;;
  *) echo "::warning::unrecognized anchor '${ANCHOR}' — skipping token publish"; exit 0 ;;
esac
AT="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
ROW="$(printf '{"leg":"%s","at":"%s","prompt":%s,"completion":%s,"total":%s}' \

